export function invoiceVoucherRefs(kind: ARAPKind,invoiceNo: string,source?: string,sourceVoucherNo?: string){
  const paymentLabel=kind==='AR'?'收款':'付款',openingRef=source==='opening'?'期初明細':source==='voucher'?(sourceVoucherNo||'來源 Voucher'):'來源未提供';
  const refs=[`<span class="voucher-ref">開票：<b>${esc(openingRef)}</b></span>`];
  const paymentRefs=[...new Set(store.allocations.filter(x=>x.kind===kind&&x.invoiceNo===invoiceNo&&dateInFiscalYear(x.date)).map(x=>x.voucher).filter(Boolean))];
  if(paymentRefs.length)refs.push(`<span class="voucher-ref">${paymentLabel}：${paymentRefs.map(v=>`<b>${esc(v)}</b>`).join('、')}</span>`);
  else refs.push(`<span class="voucher-ref">${paymentLabel}：<b>未有記錄</b></span>`);
  return refs.join('');
}

export function invoiceVoucherText(kind: ARAPKind,invoiceNo: string,source?: string,sourceVoucherNo?: string){
  const paymentLabel=kind==='AR'?'收款':'付款',openingRef=source==='opening'?'期初明細':source==='voucher'?(sourceVoucherNo||'來源 Voucher'):'來源未提供';
  const paymentRefs=[...new Set(store.allocations.filter(x=>x.kind===kind&&x.invoiceNo===invoiceNo&&dateInFiscalYear(x.date)).map(x=>x.voucher).filter(Boolean))];
  return `開票：${openingRef}；${paymentLabel}：${paymentRefs.length?paymentRefs.join('、'):'未有記錄'}`;
}

export function partyVoucherPayments(kind: ARAPKind,accountName: string){
  const party=accountName.replace(/^Accounts (Receivable|Payable) of /,'');
  return store.vouchers.filter(v=>dateInFiscalYear(v.date)).flatMap(v=>v.lines.filter(line=>line.account===accountName).map(line=>({date:v.date,voucher:v.no,amount:kind==='AR'?line.credit:line.debit,invoices:[...new Set(store.allocations.filter(x=>x.kind===kind&&x.voucher===v.no&&normalParty(x.party)===normalParty(party)).map(x=>x.invoiceNo))],specified:v.allocationInvoice||''}))).filter(x=>x.amount>0).sort((a,b)=>a.date.localeCompare(b.date)||a.voucher.localeCompare(b.voucher));
}

export function purchaseRemark(invoiceNo: string){const payments=store.allocations.filter(x=>x.kind==='AP'&&x.invoiceNo===invoiceNo&&dateInFiscalYear(x.date)).sort((a,b)=>a.date.localeCompare(b.date));if(!payments.length)return'未付款';const last=payments[payments.length-1],d=new Date(last.date+'T00:00:00');return `paid on ${d.toLocaleString('en',{month:'short'})} ${d.getFullYear()}`}

export function salesRemark(invoiceNo: string){return store.invoiceRemarks[invoiceNo]||'未收款'}

export function reportTransactionRows(isPurchase: boolean): TransactionRow[]{
  const kind=isPurchase?'AP':'AR',invoiceSource=isPurchase?store.purchaseInvoices:store.salesInvoices;
  const invoices=invoiceSource.filter(r=>dateInFiscalYear(r[0])).map(r=>({date:r[0],invoice:r[1],voucherHtml:invoiceVoucherRefs(kind,r[1],r[4],r[5]),voucherText:invoiceVoucherText(kind,r[1],r[4],r[5]),name:r[2],amount:r[3],remark:isPurchase?purchaseRemark(r[1]):salesRemark(r[1]),source:'invoice'}));
  const postings=store.vouchers.filter(v=>dateInFiscalYear(v.date)).flatMap(v=>{
    const partyLine=v.lines.find(line=>line.account.startsWith(isPurchase?'Accounts Payable of ':'Accounts Receivable of '));
    const party=partyLine?partyLine.account.replace(/^Accounts (Receivable|Payable) of /,''):v.desc;
    return v.lines.filter(line=>{const a=store.accounts.find(x=>x.name===line.account);return a&&accountHasFiscalActivity(a)&&(isPurchase?(a.type==='成本'&&/purchase/i.test(a.name)&&line.debit>0):(a.type==='收入'&&/sales/i.test(a.name)&&line.credit>0))}).map(line=>({date:v.date,invoice:v.allocationInvoice||'—',voucherHtml:`<b>${esc(v.no)}</b>`,voucherText:v.no,name:party||line.detail||v.desc,amount:isPurchase?line.debit:line.credit,remark:line.detail||v.desc||'直接經 voucher 入賬',source:'voucher'}));
  });
  return invoices.concat(postings).sort((a,b)=>a.date.localeCompare(b.date)||a.voucherText.localeCompare(b.voucherText));
}

export function salesChannel(row: TransactionRow){
  const party=String(row.name||'').trim(),normal=normalParty(party);
  const hasAR=store.accounts.some(a=>a.name.startsWith('Accounts Receivable of ')&&normalParty(a.name.replace('Accounts Receivable of ',''))===normal);
  if(hasAR)return'ar';
  if(/pmq/i.test(party))return'pmq';
  return'online';
}

