export function fiscalMonths(): FiscalMonth[]{const fy=selectedFiscalYear(),months=[];for(let i=0;i<12;i++){const d=new Date(fy.start,i+3,1),year=d.getFullYear(),month=d.getMonth()+1,last=new Date(year,month,0).getDate(),short=d.toLocaleString('en',{month:'short'})+' '+String(year).slice(-2),long=d.toLocaleString('en',{month:'long'})+' '+year;months.push({key:`${year}-${pad2(month)}`,short,long,end:`${last} ${d.toLocaleString('en',{month:'short'})} ${year}`})}return months}

export const selectedFiscalMonth=()=>{const mm=store.reportState.month;return mm?fiscalMonths().find(m=>m.key===mm.key):null;};

export const accountValue=(name: string,fallback: Cents=0 as Cents,types: string[] | null=null): Cents=>{const account=store.accounts.find(a=>a.name===name);if(account)return types&&!types.includes(account.type)?0 as Cents:accountBalance(account);if(store.accounts.some(a=>a.originalName===name))return 0 as Cents;return selectedFiscalYear().start===2023&&!store.deletedDataYears.has('2023')?fallback:0 as Cents};

export const reportTransactionTotal=(isPurchase: boolean): Cents=>reportTransactionRows(isPurchase).reduce((sum,row)=>sum+row.amount,0) as Cents;

export function currentYearProfitLoss(): Cents{return (-fiscalAccounts().filter(a=>['收入','成本','費用'].includes(a.type)).reduce((sum,a)=>sum+accountSignedBalance(a),0)) as Cents}

export function customAccountAmount(account: Account,cumulative: boolean){
  const selected=selectedFiscalMonth();
  if(!selected)return accountBalance(account);
  const fy=selectedFiscalYear(),base: Cents=cumulative?((fy.start===2023&&!store.deletedDataYears.has(fy.key)?account.importedBalance:0 as Cents)+openingNaturalBalance(account,fy)) as Cents:0 as Cents;
  return store.vouchers.reduce((sum: Cents,v)=>{
    if(!dateInFiscalYear(v.date))return sum;const month=v.date.slice(0,7);if(cumulative?month>selected.key:month!==selected.key)return sum;
    const lineTotal=v.lines.filter(line=>line.account===account.name).reduce((lineSum,line)=>lineSum+(account.side==='dr'?line.debit-line.credit:line.credit-line.debit),0);
    return (sum+lineTotal) as Cents;
  },base);
}

export function findAccountByName(name: unknown){const term=String(name||'').trim().toLowerCase();return store.accounts.find(account=>account.name.toLowerCase()===term||String(account.originalName||'').toLowerCase()===term)}

export function stockAccountAmountThrough(account: Account | null | undefined,monthKey: string | null | undefined,creditNormal=false): Cents{
  if(!account||!monthKey)return 0 as Cents;const fy=selectedFiscalYear(),entry=openingEntry(fy,account.name),signed=(debit: Cents,credit: Cents): Cents=>((creditNormal?credit-debit:debit-credit) as Cents);
  return (signed(entry.debit,entry.credit)+store.vouchers.reduce((sum,voucher)=>{
    if(!dateInFiscalYear(voucher.date,fy)||voucher.date.slice(0,7)>monthKey)return sum;
    return sum+voucher.lines.filter(line=>line.account===account.name).reduce((lineSum,line)=>lineSum+signed(line.debit,line.credit),0);
  },0)) as Cents;
}

export function monthlyStockAmounts(selected: FiscalMonth | null | undefined){
  if(!selected)return null;const months=fiscalMonths(),monthIndex=months.findIndex(month=>month.key===selected.key),openingAccount=findAccountByName('Opening Stock'),closingAccount=findAccountByName('Closing Stock Adjustment');
  const opening=monthIndex===0?(openingAccount?stockAccountAmountThrough(openingAccount,selected.key):0):(closingAccount?stockAccountAmountThrough(closingAccount,months[monthIndex-1].key,true):0);
  const closing=closingAccount?stockAccountAmountThrough(closingAccount,selected.key,true):0;
  return{opening,closing};
}

export function profitLossAccountAmount(name: string,_fallback?: Cents,_types?: string[]): Cents{
  const selected=selectedFiscalMonth(),account=findAccountByName(name);
  if(account)return selected?customAccountAmount(account,false):accountBalance(account);
  return 0 as Cents;
}

