export const reconcileKey=(kind: ARAPKind,party: string,month: { key: string } | null | undefined=store.reportState.month)=>`${store.selectedFiscalKey}|${month?.key||'all'}|${kind}|${normalParty(party)}`;

export const periodMatches=(date: string)=>store.reportState.month===null?dateInFiscalYear(date):String(date).slice(0,7)===store.reportState.month.key;

export function currentReconcileState(kind: ARAPKind,party: string,invoiceOutstanding: Cents,accountBalance: Cents){
  const difference=(invoiceOutstanding-Math.abs(accountBalance)) as Cents,saved=store.reconciliationConfirmations[reconcileKey(kind,party)];
  const confirmed=Boolean(saved&&saved.invoiceOutstanding===invoiceOutstanding&&saved.accountBalance===accountBalance&&saved.difference===difference);
  return{difference,saved,confirmed,matched:difference===0};
}

export function reconcileDraftMetrics(){
  const paidByInvoice: Record<string, Cents>={};store.reconcilePaymentDraft.forEach(p=>{paidByInvoice[p.invoiceNo]=((paidByInvoice[p.invoiceNo]||0)+p.amount) as Cents});
  const invoiceOutstanding=store.reconcileInvoiceDraft.reduce((sum,item)=>sum+Math.max(0,item.amount-(paidByInvoice[item.invoiceNo]||0)),0) as Cents;
  const account=store.accounts.find(a=>a.name===store.reconciliationContext!.accountName),accountBalance=account?accountSignedBalance(account):0 as Cents;
  return{invoiceOutstanding,accountBalance,difference:(invoiceOutstanding-Math.abs(accountBalance)) as Cents};
}

export function updateReconcileSummary(){
  if(!store.reconciliationContext)return;const metrics=reconcileDraftMetrics();
  (document.getElementById('reconcileInvoiceTotal') as HTMLElement).textContent=money(metrics.invoiceOutstanding);(document.getElementById('reconcileAccountBalance') as HTMLElement).textContent=money(metrics.accountBalance);const diff=(document.getElementById('reconcileDifference') as HTMLElement);diff.textContent=money(metrics.difference);diff.style.color=metrics.difference===0?'var(--good)':'var(--warn)';
}

